-- Execute this once in the database dedicated to one PWA installation.
-- The API also creates these tables at startup; this file is provided for controlled Plesk deployments.
CREATE TABLE IF NOT EXISTS EC_centros (id INT AUTO_INCREMENT PRIMARY KEY, parque_centro VARCHAR(255) NOT NULL, localidad VARCHAR(255) NOT NULL, email_primario VARCHAR(255) NOT NULL, email_secundario VARCHAR(255) NULL, onedrive_folder_path VARCHAR(1000) NULL, activo BOOLEAN NOT NULL DEFAULT TRUE, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3));
CREATE TABLE IF NOT EXISTS EC_templates (id INT AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(255) NOT NULL, asunto_template LONGTEXT NOT NULL, cuerpo_template LONGTEXT NOT NULL, saludo_default VARCHAR(120) NULL, activo BOOLEAN NOT NULL DEFAULT TRUE, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3));
CREATE TABLE IF NOT EXISTS EC_lotes (id INT AUTO_INCREMENT PRIMARY KEY, anio INT NOT NULL, mes_numero VARCHAR(2) NOT NULL, mes_nombre VARCHAR(40) NOT NULL, extension_archivo VARCHAR(20) NOT NULL, template_id INT NOT NULL, estado VARCHAR(30) NOT NULL DEFAULT 'borrador', sent_at DATETIME(3) NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), UNIQUE KEY ec_lote_periodo (anio, mes_numero, extension_archivo));
CREATE TABLE IF NOT EXISTS EC_items (id INT AUTO_INCREMENT PRIMARY KEY, lote_id INT NOT NULL, centro_id INT NULL, parque_centro_snapshot VARCHAR(255) NOT NULL, localidad_snapshot VARCHAR(255) NOT NULL, destinatarios_json LONGTEXT NOT NULL, asunto LONGTEXT NOT NULL, cuerpo LONGTEXT NOT NULL, archivo_nombre VARCHAR(255) NOT NULL, onedrive_path_esperado VARCHAR(1000) NULL, storage_path VARCHAR(1000) NULL, storage_original_file_name VARCHAR(255) NULL, archivo_origen VARCHAR(20) NOT NULL DEFAULT 'ninguno', archivo_estado VARCHAR(30) NOT NULL DEFAULT 'pendiente', envio_estado VARCHAR(30) NOT NULL DEFAULT 'pendiente', error LONGTEXT NULL, sent_at DATETIME(3) NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), INDEX ec_items_lote (lote_id));
CREATE TABLE IF NOT EXISTS EC_integrations (id INT AUTO_INCREMENT PRIMARY KEY, device_id VARCHAR(128) NOT NULL, access_token_encrypted LONGTEXT NULL, refresh_token_encrypted LONGTEXT NULL, expires_at DATETIME(3) NULL, account_email VARCHAR(255) NULL, root_path VARCHAR(1000) NULL, status VARCHAR(30) NOT NULL DEFAULT 'disconnected', created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), UNIQUE KEY ec_integration_device (device_id));
